import { readFileSync } from 'fs';

const gitconfig = readFileSync('/home/user/.gitconfig', 'utf8');
const match = gitconfig.match(/x-access-token:([^@]+)@github\.com\/ibb142\/ivx-holdings-platform/);
if (!match) {
  console.error('GitHub token not found in gitconfig');
  process.exit(1);
}
const token = match[1];

const repo = 'ibb142/ivx-holdings-platform';
const tag = `apk-qa-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Date.now()}`;
const apkPath = '/home/user/rork-app/expo/android/app/build/outputs/apk/qa/app-qa.apk';

// Create release
const releaseRes = await fetch(`https://api.github.com/repos/${repo}/releases`, {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${token}`,
    'Accept': 'application/vnd.github+json',
    'Content-Type': 'application/json',
    'X-GitHub-Api-Version': '2022-11-28'
  },
  body: JSON.stringify({
    tag_name: tag,
    name: `IVX QA APK ${new Date().toISOString().slice(0,10)}`,
    body: 'Debug-signed QA Android APK built from latest source.',
    draft: false,
    prerelease: true
  })
});

if (!releaseRes.ok) {
  const err = await releaseRes.text();
  console.error(`Release create failed HTTP ${releaseRes.status}: ${err.slice(0, 500)}`);
  process.exit(1);
}

const release = await releaseRes.json();
console.log(`Release created: ${release.html_url}`);

// Upload APK
const apkData = readFileSync(apkPath);
const uploadUrl = release.upload_url.replace('{?name,label}', '?name=app-qa.apk');
const uploadRes = await fetch(uploadUrl, {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${token}`,
    'Accept': 'application/vnd.github+json',
    'Content-Type': 'application/vnd.android.package-archive',
    'X-GitHub-Api-Version': '2022-11-28'
  },
  body: apkData
});

if (!uploadRes.ok) {
  const err = await uploadRes.text();
  console.error(`APK upload failed HTTP ${uploadRes.status}: ${err.slice(0, 500)}`);
  process.exit(1);
}

const asset = await uploadRes.json();
console.log(`APK uploaded: ${asset.browser_download_url}`);

